// Sala 3 · "A Balança": number series generated by rules, increasing in difficulty.
import {int,pick} from './daily.js';

export const meta={
 'pt-BR':{title:'A Balança',lede:'Cinco sequências, cada uma com uma regra. Qual número vem depois?',
  how:['Olhe a diferença entre os números, a razão entre eles, ou se há duas sequências intercaladas.','Digite o próximo número e confirme. Cada sequência tem uma tentativa.','As últimas sequências combinam regras.']},
 en:{title:'The Scale',lede:'Five sequences, each following a rule. Which number comes next?',
  how:['Look at the differences, the ratios, or whether two sequences are interleaved.','Type the next number and confirm. Each sequence gets one attempt.','The last sequences combine rules.']}
};
const T={
 'pt-BR':{of:(k,n)=>`Sequência ${k} de ${n}`,confirm:'Confirmar',right:'Certo!',wrong:a=>`Era ${a}.`,share:(n,e,c)=>`BOWLER TEST · A Balança #${n}\n${e} ${c}/5`,summary:(c,s)=>`${c} de 5 sequências em ${s}s.`},
 en:{of:(k,n)=>`Sequence ${k} of ${n}`,confirm:'Confirm',right:'Right!',wrong:a=>`It was ${a}.`,share:(n,e,c)=>`BOWLER TEST · The Scale #${n}\n${e} ${c}/5`,summary:(c,s)=>`${c} of 5 sequences in ${s}s.`}
};
const GEN=[
 r=>{const a=int(r,1,20),d=int(r,3,9)*(r()<.2?-1:1);return [...Array(6)].map((_,i)=>a+d*i+(d<0?60:0));},
 r=>{if(r()<.5){const a=int(r,1,4),q=int(r,2,3);return [...Array(6)].map((_,i)=>a*q**i);}const a=int(r,1,10),d=int(r,1,4),k=int(r,1,3);let x=a,s=d;return [...Array(6)].map(()=>{const v=x;x+=s;s+=k;return v;});},
 r=>{const a=int(r,1,15),d=int(r,2,6),b=int(r,20,40),e=-int(r,1,4);return [...Array(7)].map((_,i)=>i%2===0?a+d*(i/2):b+e*((i-1)/2));},
 r=>{const a=int(r,1,5),b=int(r,2,7);const s=[a,b];while(s.length<7)s.push(s.at(-1)+s.at(-2));return s;},
 r=>{const kind=pick(r,['muladd','squares','alt']);
  if(kind==='muladd'){const m=2,c=pick(r,[1,-1,2,3]),x0=int(r,2,6);const s=[x0];while(s.length<6)s.push(s.at(-1)*m+c);return s;}
  if(kind==='squares'){const o=int(r,1,4),c=int(r,-3,5);return [...Array(6)].map((_,i)=>(i+o)**2+c);}
  const x0=int(r,2,9),a=int(r,2,3),b=int(r,3,8);const s=[x0];while(s.length<7)s.push(s.length%2?s.at(-1)*a:s.at(-1)+b);return s;}
];
export function generate(r,level){const seq=GEN[level](r);return {shown:seq.slice(0,-1),answer:seq.at(-1)};}

export function mount(root,ctx){
 const t=T[ctx.lang],items=GEN.map((_,i)=>generate(ctx.rng('s'+i),i));
 const st=ctx.saved||{answers:[],started:Date.now(),done:false};
 root.innerHTML=`<div class="num"><div class="mx-top"><span class="num-step"></span><span class="num-dots"></span></div><div class="num-seq"></div>
  <form class="num-form" autocomplete="off"><input name="a" inputmode="numeric" pattern="-?[0-9]*" aria-label="?"><button class="primary">${t.confirm}</button></form><p class="num-msg" aria-live="polite"></p></div>`;
 const seq=root.querySelector('.num-seq'),form=root.querySelector('form'),msg=root.querySelector('.num-msg');
 const dots=()=>root.querySelector('.num-dots').textContent=items.map((_,i)=>i<st.answers.length?(st.answers[i]?'●':'×'):'○').join('');
 let k=st.answers.length,locked=false;
 const show=()=>{dots();if(k>=items.length){finish();return;}locked=false;msg.textContent='';root.querySelector('.num-step').textContent=t.of(k+1,items.length);
  seq.innerHTML=items[k].shown.map(v=>`<span>${v}</span>`).join('<i>·</i>')+'<i>·</i><span class="num-q">?</span>';form.a.value='';form.hidden=false;form.a.focus();};
 form.onsubmit=e=>{e.preventDefault();if(locked||form.a.value.trim()==='')return;locked=true;const ok=Number(form.a.value)===items[k].answer;st.answers.push(ok);ctx.save(st);
  seq.querySelector('.num-q').textContent=items[k].answer;seq.querySelector('.num-q').classList.add(ok?'right':'wrong');msg.textContent=ok?t.right:t.wrong(items[k].answer);dots();k++;setTimeout(show,ok?800:1600);};
 const finish=()=>{form.hidden=true;seq.innerHTML='';if(st.done)return;st.done=true;st.seconds=Math.round((Date.now()-st.started)/1000);ctx.save(st);
  const c=st.answers.filter(Boolean).length;ctx.finish({summary:t.summary(c,st.seconds),share:t.share(ctx.number,st.answers.map(a=>a?'🟩':'🟥').join(''),c),score:{correct:c,seconds:st.seconds}});};
 if(st.done){dots();form.hidden=true;}else show();
}
